include!("guard_prefix.rs");
use std::collections::HashSet;
fn hash(v:&[Op])->String{let mut h=Sha3_256::new();for o in v{for x in [o.kind as u64,o.q_control2.0,o.q_control1.0,o.q_target.0,o.c_target.0,o.c_condition.0,o.r_target.0]{h.update(x.to_le_bytes());}}format!("{:x}",h.finalize())}
fn edits(old:&[Op],new:&[Op])->Vec<(usize,usize)>{let(mut out,mut j,mut ordinal)=(vec![],0,0);for(i,o)in old.iter().enumerate(){let current=ordinal;if o.kind==K::CCX{ordinal+=1;}if new.get(j)==Some(o){j+=1;continue;}assert_eq!(o.kind,K::CCX,"only a CCX may be replaced");let mut initial=None;if new[j].kind==K::CX{initial=Some(new[j]);j+=1;}let p=new[j];let x=new[j+1];let pop=new[j+2];assert_eq!(p.kind,K::PushCondition);assert_ne!(p.c_condition.0,NO);assert_eq!(x.kind,K::CX);assert_eq!(x.q_control2.0,NO);assert_eq!(x.q_target,o.q_target);assert_eq!(x.c_condition,o.c_condition);assert!([o.q_control1,o.q_control2].contains(&x.q_control1));assert_eq!(pop.kind,K::PopCondition);if let Some(first)=initial{assert_eq!(first,x);}out.push((current,i));j+=3;}assert_eq!(j,new.len());out}
fn main(){let r=std::path::PathBuf::from(std::env::args().nth(1).unwrap());let ws=r.parent().unwrap();let base=io::load_ops(ws.join("product-pareto-20261019/candidate-parent4/ops.bin").to_str().unwrap());let simple=io::load_ops(ws.join("product-classical-factors-refresh-20261019/parent4.ops.bin").to_str().unwrap());let captured=io::load_ops(ws.join("product-captured-factors-20261019/captured.ops.bin").to_str().unwrap());let factored=io::load_ops(ws.join("product-captured-factors-20261019/factored.ops.bin").to_str().unwrap());assert_eq!(hash(&base),"97c40ed1dd3f5123c9554ebf29c54c433960804c0effce63dc7bba52844ae9ae");assert_eq!(hash(&simple),"f64a9d8c59cdc89e9b683988da84eb34fa78c5a884f0324ce824e4c07a00fa53");assert_eq!(hash(&captured),"e0fa1dfb4871349eda590b0fa92e40d92afdf6ca17c9ad35393d588b2f1e8c8a");assert_eq!(hash(&factored),"6c823d3cfbdb50dd3f055239acad72824b295b3c87dc13bb719655dff58a532e");let a=edits(&base,&simple);let b=edits(&captured,&factored);assert_eq!(a.len(),8);assert_eq!(b.len(),16);let shape=|v:&[Op]|v.iter().filter(|o|o.kind==K::CCX).map(|o|(o.q_control2,o.q_control1,o.q_target)).collect::<Vec<_>>();assert_eq!(shape(&base),shape(&captured));let aa:HashSet<_>=a.iter().map(|x|x.0).collect();let bb:HashSet<_>=b.iter().map(|x|x.0).collect();let subset=aa.is_subset(&bb);let extras:HashSet<_>=b.iter().filter(|x|!aa.contains(&x.0)).map(|x|x.1).collect();drop(base);drop(simple);drop(factored);
 let nb=captured.iter().flat_map(|o|[o.c_target.0,o.c_condition.0]).filter(|&x|x!=NO).max().unwrap_or(0)as usize+1;let mut d=BoolDag::new();let mut c=vec![0;nb];for o in &captured{if o.kind==K::AppendToRegister&&o.c_target.0!=NO{c[o.c_target.0 as usize]=d.node(B::Input(o.c_target.0));}}let(mut base,mut stack,mut events)=(1,vec![],0);let mut rows=vec![];
 for(i,o)in captured.iter().enumerate(){if o.kind==K::PushCondition{stack.push(base);base=d.and(base,c[o.c_condition.0 as usize]);continue;}if o.kind==K::PopCondition{base=stack.pop().unwrap();continue;}let eff=if o.c_condition.0==NO{base}else{d.and(base,c[o.c_condition.0 as usize])};if extras.contains(&i){rows.push(serde_json::json!({"captured_source_op":i,"effective_guard_node":eff,"identically_false":eff==0,"direct_condition":o.c_condition.0}));}let ct=o.c_target.0 as usize;match o.kind{K::Hmr=>{let fresh=d.node(B::Mr(events));c[ct]=d.select(c[ct],fresh,eff);events+=1;},K::R=>events+=1,K::BitInvert=>c[ct]=d.xor(c[ct],eff),K::BitStore0=>c[ct]=d.select(c[ct],0,eff),K::BitStore1=>c[ct]=d.select(c[ct],1,eff),_=>{}}}
 assert!(stack.is_empty());assert_eq!(rows.len(),extras.len());let all_zero=rows.iter().all(|x|x["identically_false"]==true);let result=serde_json::json!({"status":if subset&&all_zero{"ALL_ADDITIONAL_STATIC_REDUCTIONS_ARE_UNIVERSALLY_INACTIVE"}else{"ADDITIONAL_EXECUTED_BENEFIT_NOT_DISPROVED"},"simple_removed_CCX_ordinals":aa.iter().copied().collect::<BTreeSet<_>>(),"captured_removed_CCX_ordinals":bb.iter().copied().collect::<BTreeSet<_>>(),"simple_set_is_subset":subset,"every_original_CCX_operand_order_verified":true,"all_outside_replacement_operations_byte_identical":true,"additional_captured_deletions":rows,"all_additional_guards_false":all_zero,"bool_nodes":d.nodes.len(),"bool_cuts":d.cuts,"scope":"Universal classical guard proof of executed-cost equality under the same input/RNG; not a scored benchmark or statistical gate."});std::fs::write(r.join("RESULT.json"),serde_json::to_string_pretty(&result).unwrap()).unwrap();println!("{}",result);}
